mapper.insert:
INSERT INTO lost_police ( atc_id, lst_place, lst_prdt_nm, lst_sbjt, lst_ymd, prdt_cl_nm, prdt_category, done, is_deleted ) VALUES
( #{item.atcId}, LEFT(#{item.lstPlace}, 100), LEFT(#{item.lstPrdtNm}, 100), #{item.lstSbjt}, /* 📌 text 타입이므로 굳이 LEFT로 안 자르고 원본 그대로 삽입 */ #{item.lstYmd}, LEFT(#{item.prdtClNm}, 50), LEFT(#{item.prdtCategory}, 50), 0, 0 )
ON DUPLICATE KEY UPDATE /* 중복 데이터 발생 시, 제목(lst_sbjt)에 '완료'가 포함되어 있다면 is_deleted를 1로 변경 */ is_deleted = IF(VALUES(lst_sbjt) LIKE '%완료%', 1, is_deleted),
/* 제목에 '완료'가 들어가서 처리가 끝난 건이라면 done 컬럼도 함께 1로 상태 변경 */ done = IF(VALUES(lst_sbjt) LIKE '%완료%', 1, done),
/* 무의미한 수정을 방지하기 위해 나머지 데이터는 기존 값 그대로 유지 (또는 자동 갱신) */ lst_place = lst_place, lst_prdt_nm = lst_prdt_nm, lst_sbjt = lst_sbjt, lst_ymd = lst_ymd, prdt_cl_nm = prdt_cl_nm, prdt_category = prdt_category
